<script setup>
import { computed, onMounted, ref } from 'vue';
import PortalLayout from '../layouts/PortalLayout.vue';
import api from '../services/api';

const modules=[['','All modules'],['subjects','Subjects'],['classes','Class assignments'],['firms','Firms'],['announcements','Announcements'],['users','User accounts'],['schedule_images','Schedule images']];
const filters=ref({module:'',search:''}),rows=ref([]),total=ref(0),page=ref(1),selected=ref([]),previews=ref({}),loading=ref(false),working=ref(false),error=ref(''),notice=ref('');
const chosen=computed(()=>rows.value.filter(row=>selected.value.includes(`${row.module}:${row.id}`)));
function label(module){return modules.find(([value])=>value===module)?.[1]||module;}
async function load(){loading.value=true;error.value='';selected.value=[];previews.value={};try{let result=await api.get('/archive',{params:{...filters.value,page:page.value}});if(!result.data.data.rows.length&&result.data.data.total&&page.value>1){page.value=Math.max(1,Math.ceil(result.data.data.total/20));result=await api.get('/archive',{params:{...filters.value,page:page.value}});}rows.value=result.data.data.rows;total.value=result.data.data.total;}catch(e){error.value=e.response?.data?.message||'Could not load archived records.';}finally{loading.value=false;}}
async function preview(){error.value='';previews.value={};try{for(const row of chosen.value){const key=`${row.module}:${row.id}`;previews.value[key]=(await api.get(`/archive/${row.module}/${row.id}/preview`)).data.data;}}catch(e){error.value=e.response?.data?.message||'Could not preview every selected record.';previews.value={};}}
function toggleAll(event){selected.value=event.target.checked?rows.value.map(row=>`${row.module}:${row.id}`):[];previews.value={};}
function toggle(){previews.value={};}
async function restore(row){const reason=window.prompt(`Why restore “${row.title}”?`);if(!reason?.trim())return;working.value=true;error.value='';notice.value='';try{await api.patch(`/archive/${row.module}/${row.id}/restore`,{reason:reason.trim()});notice.value='Record restored. Review it in its module before publishing or enabling access.';await load();}catch(e){error.value=e.response?.data?.message||'Could not restore this record.';}finally{working.value=false;}}
async function restoreSelected(){if(!chosen.value.length)return;const reason=window.prompt(`Reason for restoring ${chosen.value.length} selected records:`);if(!reason?.trim())return;if(!window.confirm(`Restore ${chosen.value.length} selected archived records? User accounts will remain disabled; unpublished items become drafts.`))return;working.value=true;error.value='';notice.value='';let done=0;const failures=[];for(const row of chosen.value){try{await api.patch(`/archive/${row.module}/${row.id}/restore`,{reason:reason.trim()});done++;}catch(e){failures.push(`${row.title}: ${e.response?.data?.message||'restore failed'}`);}}await load();notice.value=`Restored ${done} record${done===1?'':'s'}. Review them before enabling or publishing.`;if(failures.length)error.value=`${failures.length} record(s) could not be restored: ${failures.join(' ')}`;working.value=false;}
async function remove(row){let details=previews.value[`${row.module}:${row.id}`];if(!details){try{details=(await api.get(`/archive/${row.module}/${row.id}/preview`)).data.data;previews.value={...previews.value,[`${row.module}:${row.id}`]:details};}catch(e){error.value=e.response?.data?.message||'Could not preview this record.';return;}}if(!details.canDelete){error.value=details.reason;return;}const reason=window.prompt(`Permanent deletion cannot be undone. Why delete “${row.title}”?`);if(!reason?.trim())return;if(!window.confirm(`Permanently delete “${row.title}”? Related inbox copies and private images will be removed. Audit events remain.`))return;working.value=true;error.value='';notice.value='';try{const result=await api.delete(row.module==='firms'?`/firms/${row.id}`:`/archive/${row.module}/${row.id}`,{data:{reason:reason.trim()}});notice.value=result.data.message||'Archived record permanently deleted.';await load();window.dispatchEvent(new Event('sbaa:notifications'));}catch(e){error.value=e.response?.data?.message||'Deletion was blocked. The record was not removed.';}finally{working.value=false;}}
async function removeSelected(){const targets=[...chosen.value];if(!targets.length)return;await preview();if(error.value)return;const blocked=targets.filter(row=>!previews.value[`${row.module}:${row.id}`]?.canDelete);if(blocked.length){error.value=`${blocked.length} selected record(s) cannot be deleted. Review the blockers below and deselect them.`;return;}const reason=window.prompt(`Reason for permanently deleting ${targets.length} selected records:`);if(!reason?.trim())return;if(!window.confirm(`Permanently delete ${targets.length} archived records and related inbox copies? This cannot be undone. Audit events remain.`))return;working.value=true;error.value='';notice.value='';let done=0;const failures=[];for(const row of targets){try{await api.delete(row.module==='firms'?`/firms/${row.id}`:`/archive/${row.module}/${row.id}`,{data:{reason:reason.trim()}});done++;}catch(e){failures.push(`${row.title}: ${e.response?.data?.message||'deletion failed'}`);}}await load();window.dispatchEvent(new Event('sbaa:notifications'));notice.value=`Permanently deleted ${done} record${done===1?'':'s'}.`;if(failures.length)error.value=`${failures.length} record(s) were not deleted: ${failures.join(' ')}`;working.value=false;}
onMounted(load);
</script>
<template><PortalLayout title="Archive"><div class="dashboard content-page"><div class="page-heading"><div><p class="eyebrow">INFORMATION & RECORDS</p><h2>Archive center</h2><p>Review archived records before restoring or permanently deleting them. Academic history and audit records are protected.</p></div></div>
<p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="success-message" role="status">{{notice}}</p>
<section class="panel"><h3>Find archived records</h3><form class="toolbar" @submit.prevent="page=1;load()"><label>Module<select v-model="filters.module"><option v-for="[value,name] in modules" :key="value" :value="value">{{name}}</option></select></label><label>Search<input v-model="filters.search" maxlength="100" placeholder="Record title or code"/></label><button class="secondary-button">Filter archive</button><button type="button" class="text-button" @click="filters={module:'',search:''};page=1;load()">Clear filters</button></form><p class="empty">{{total}} matching archived record{{total===1?'':'s'}}</p><p v-if="loading" class="empty">Loading archive…</p><template v-else><label v-if="rows.length" class="archive-select-all"><input type="checkbox" :checked="selected.length===rows.length" @change="toggleAll"/>Select this page</label><div v-if="rows.length" class="record-list"><article v-for="row in rows" :key="`${row.module}:${row.id}`" class="record-row"><div class="archive-row-main"><label><input v-model="selected" type="checkbox" :value="`${row.module}:${row.id}`" @change="toggle"/><span class="sr-only">Select {{row.title}}</span></label><div><strong>{{row.title}}</strong><span>{{label(row.module)}} · Record #{{row.id}}</span><small>Archived {{row.archivedAt?new Date(row.archivedAt).toLocaleString('en-PH',{timeZone:'Asia/Manila'}):'date not recorded'}}{{row.archivedBy?` · By account #${row.archivedBy}`:''}}</small></div></div><div class="inline-actions"><button class="text-button" :disabled="working" @click="selected=[`${row.module}:${row.id}`];preview()">Preview</button><button class="text-button" :disabled="working" @click="restore(row)">Restore</button><button class="text-button destructive" :disabled="working" @click="remove(row)">Delete permanently</button></div></article></div><p v-else class="empty">No archived records match these filters.</p><div class="pagination"><button :disabled="page===1" @click="page--;load()">Previous</button><span>Page {{page}} · {{total}} records</span><button :disabled="page*20>=total" @click="page++;load()">Next</button></div></template></section>
<section v-if="chosen.length" class="panel narrow-panel"><h3>Selected records ({{chosen.length}})</h3><p>Preview the selected records and their deletion limits. Bulk actions process records individually and report any failures.</p><div class="inline-actions"><button class="secondary-button" :disabled="working" @click="preview">Preview selection</button><button class="primary" :disabled="working" @click="restoreSelected">Restore selection</button><button class="secondary-button destructive" :disabled="working" @click="removeSelected">Delete selected permanently</button></div><ul v-if="Object.keys(previews).length" class="archive-preview"><li v-for="row in chosen" :key="`${row.module}:${row.id}`"><strong>{{row.title}}</strong> — Restore as {{previews[`${row.module}:${row.id}`]?.restoreStatus}}. {{previews[`${row.module}:${row.id}`]?.reason}} <span v-if="!previews[`${row.module}:${row.id}`]?.canDelete">Permanent deletion blocked.</span></li></ul></section>
</div></PortalLayout></template>
<style scoped>.archive-select-all,.archive-row-main{display:flex;align-items:flex-start;gap:.75rem}.archive-row-main>div{display:grid;gap:.2rem}.archive-row-main{min-width:0}.record-row{display:flex;flex-wrap:wrap;gap:1rem}.record-row>.inline-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:.5rem;margin-left:auto}.archive-preview{padding-left:1.5rem}.archive-preview li+li{margin-top:.7rem}@media(max-width:700px){.record-row>.inline-actions{justify-content:flex-start;margin-left:0;width:100%}}</style>
